head.script:
// https://inswave01.atlassian.net/browse/WAEA-1211
// https://inswave01.atlassian.net/browse/WAEA-1202
// 테스트 설명, 유효성 값 설정
//  ★ _13 : dummy_xlsform (Excel 파일 서식 옵션) 계열 중 표시 형식 / 필터 옵션 - useDataFormat / useHeaderDataFormat / customToDataType / numberToText / headerAutoFilter / filterRowIndex
//     description 은 분리 샘플 공통(_1 과 동일).
scwin.tData = {
    "description" : "[gridView > M > advancedExcelDownload]<br/>GridView 컴포넌트의 데이터를 Excel 파일로 다운로드합니다.",
    "validation" : [
        "useDataFormat(선택) 파라미터로 Body Column 의 dataType 속성값에 맞게 Excel 의 표시 형식을 적용할지 설정합니다.",
        "useDataFormat(선택) 파라미터를 'true' 로 설정 시 dateType='text' 인 Body Column 은 '텍스트', dataType='number','bigDecimal' 인 Body Column 은 '숫자' 로 Excel 표시 형식을 설정합니다.",
        "useDataFormat(선택) 파라미터를 'false' 로 설정 시 Body Column 의 Excel 표시 형식을 '일반'으로 설정합니다.",
        "useDataFormat(선택) 파라미터를 생략하면 기본값 'false' 가 적용됩니다.",
        "useHeaderDataFormat(선택) 파라미터로 Header Column 의 dataType 속성값에 맞게 Excel 의 표시 형식을 적용할지 설정합니다.",
        "useHeaderDataFormat(선택) 파라미터를 'true' 로 설정 시 dateType='text' 인 Header Column 은 '텍스트', dataType='number','bigDecimal' 인 Header Column 은 '숫자' 로 Excel 표시 형식을 설정합니다.",
        "useHeaderDataFormat(선택) 파라미터를 생략하면 기본값 '' 이 적용됩니다.",
        "customToDataType(선택) 파라미터로 inputType='custom' 인 Column 의 dataType 속성값에 맞게 Excel 의 표시 형식을 적용할지 설정합니다.",
        "customToDataType(선택) 파라미터를 'true' 로 설정 시 dateType='text' 인 Column 은 '텍스트', dataType='number','bigDecimal' 인 Column 은 '숫자' 로 Excel 표시 형식을 설정합니다.",
        "customToDataType(선택) 파라미터를 생략하면 기본값 '' 이 적용됩니다.",
        "numberToText(선택) 파라미터로 dataType='number' 인 Column 의 Excel 표시 형식을 '텍스트' 로 설정할지 true/false 로 설정합니다.",
        "numberToText(선택) 파라미터로 Excel 표시 형식을 '텍스트'로 설정하면 콤마 등 포맷에 포함된 기호가 그대로 유지됩니다.",
        "numberToText(선택) 파라미터를 생략하면 기본값 false 가 적용됩니다.",
        "headerAutoFilter(선택) 파라미터로 Excel 파일의 Header 영역에 '필터' 기능을 적용할지 'true'/'false' 로 설정합니다.",
        "headerAutoFilter(선택) 파라미터를 생략하면 기본값 'false' 가 적용됩니다.",
        "filterRowIndex(선택) 파라미터로 headerAutoFilter 파라미터값이 'true' 일때 Excel 의 '필터' 기능이 적용될 Header Row 의 인덱스를 설정합니다.",
        "filterRowIndex(선택) 파라미터는 GridView 의 Header Row 를 기준으로 인덱스를 설정합니다.",
        "filterRowIndex(선택) 파라미터의 Header Row 의 인덱스는 0 부터 시작하며, Header 가 MultiLine 인 경우 각 Header Row 마다 인덱스가 설정됩니다.",
        "filterRowIndex(선택) 파라미터를 생략하면 기본값 -1 이 적용됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 : dataType 이 서로 다른 Body Column 과 MultiLine Header 를 갖춘 GridView 를 동적 생성한다.
//  · advancedExcelDownload 는 DataList 바인딩이 전제 조건이므로 dataList 속성을 반드시 설정한다.
//  · Body Column 인덱스 0:자재구분(text) 1:품목명(text) 2:재고수량(number) 3:재고금액(bigDecimal)
//                        4:관리코드(custom/text) 5:안전재고(custom/number)
//     - 0/1/3 : useDataFormat 확인용 (text -> 텍스트, bigDecimal -> 숫자)
//     - 2     : displayFormat 으로 콤마가 붙는 number Column -> numberToText 확인용
//     - 4/5   : inputType="custom" -> customToDataType 확인용
//  · Header 는 2줄(MultiLine) 이며 Header Row 인덱스 0(한글 명칭) / 1(영문 코드명) 을 filterRowIndex 로 구분한다.
//     Header Column 에도 dataType 을 지정하여 useHeaderDataFormat 을 확인한다.
scwin.comp_init = async function () {
    // 기존 target / DataList 정리
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제]\n- Body Column 인덱스 0 자재구분(dataType=text) / 1 품목명(text) / 2 재고수량(number, 콤마 표시서식) / 3 재고금액(bigDecimal) / 4 관리코드(inputType=custom, dataType=text) / 5 안전재고(inputType=custom, dataType=number), Body Row 는 5행\n- 텍스트 Column 값 앞에 (idx0 ...) (idx1 ...) (idx4 ...) 표기가 있어 파일에서 어느 Column 인지 바로 구분됨. 숫자 Column 은 자릿수가 커서 콤마가 들어가는 값임\n- Header 는 2줄(MultiLine) : Header Row 인덱스 0 은 한글 명칭(자재 구분 / 품목명 / 재고수량 / 재고금액 / 관리코드 / 안전재고), 인덱스 1 은 영문 코드명(MAT_TYPE / ITEM_NAME / STOCK_QTY / STOCK_AMT / MGR_CODE / SAFE_QTY)\n- Header Column 에도 dataType 을 지정함 (재고수량/안전재고=number, 재고금액=bigDecimal, 나머지=text)\n- 파일명 download_xlsformat, 확장자 xlsx 고정 전달(본 계열 검증 대상 아님)\n[절차]\n1. par 옵션(useDataFormat / useHeaderDataFormat / customToDataType / numberToText / headerAutoFilter / filterRowIndex) 값을 선택한다\n2. advancedExcelDownload 버튼을 클릭해 Excel 파일을 내려받는다\n[확인]\n- 이 계열은 Cell 값이 아니라 Excel 의 표시 형식과 필터 구조를 바꾸므로 값만 봐서는 차이가 보이지 않는다. 내려받은 파일을 Excel 로 열어 각 Cell 의 셀 서식 - 표시 형식(일반 / 텍스트 / 숫자) 과 Header 영역의 필터 단추로 확인한다\n- useDataFormat : true 면 텍스트 Column(자재구분 / 품목명 / 관리코드) 이 텍스트 서식, 숫자 Column(재고수량 / 재고금액 / 안전재고) 이 숫자 서식이 되는지. false 또는 미설정이면 일반 서식인지. 참고로 재고수량 Column 은 displayFormat 이 있어 미설정 상태에서도 콤마 서식이 유지되고, 재고금액 Column(bigDecimal) 은 미설정 상태에서도 숫자 서식으로 생성된다\n- useHeaderDataFormat : true 면 Header 의 재고수량 / 안전재고 칸이 숫자 서식, 나머지 Header 칸이 텍스트 서식이 되는지. 미설정이면 Header 서식이 바뀌지 않는지. 참고로 현재 엔진에서는 true 로 설정하면 Header 뿐 아니라 Body Column 서식까지 함께 바뀌고, dataType 이 bigDecimal 인 재고금액 Header 칸은 글자가 빈값으로 생성된다\n- customToDataType : true 면 custom Column 인 관리코드는 텍스트 서식, 안전재고는 숫자 서식(값도 숫자로 저장) 이 되는지. 미설정이면 custom Column 의 서식이 바뀌지 않는지\n- numberToText : true 면 재고수량 Column 값이 콤마가 들어간 문자열 그대로 저장되어 콤마가 유지되는지. false 또는 미설정이면 숫자로 저장되어 표시서식으로만 콤마가 붙는지\n- headerAutoFilter : true 면 Excel 의 Header 영역에 필터가 걸리고, false 또는 미설정이면 필터가 없는지\n- filterRowIndex : headerAutoFilter=true 인 상태에서 1 이면 Header 둘째 줄(Excel 2행) 에만 필터가 걸리는지. 미설정이거나 -1 이면 기본값이 적용되어 Header 첫째 줄부터 필터 범위가 잡히는지. headerAutoFilter 가 false 이면 filterRowIndex 를 설정해도 필터가 생기지 않는지. 참고로 현재 엔진에서는 0 을 선택하면 서버로 -1 이 전달되어 미설정과 같은 결과가 된다\n- 결과창의 서버 전달값으로 실제 서버에 전송된 6개 옵션 원문을 함께 확인. useHeaderDataFormat 은 미설정 시 요청에 담기지 않아 (미전달) 로 표시된다"', '', 'label1');

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 바인딩 DataList
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="matType" name="matType" dataType="text"></w2:column>';
    strDlt += '<w2:column id="itemName" name="itemName" dataType="text"></w2:column>';
    strDlt += '<w2:column id="stockQty" name="stockQty" dataType="number"></w2:column>';
    strDlt += '<w2:column id="stockAmt" name="stockAmt" dataType="bigDecimal"></w2:column>';
    strDlt += '<w2:column id="mgrCode" name="mgrCode" dataType="text"></w2:column>';
    strDlt += '<w2:column id="safeQty" name="safeQty" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "matType" : "(idx0 text) 전자부품", "itemName" : "(idx1 text) 칩저항 1608 10K옴", "stockQty" : 1234567, "stockAmt" : 9876543210, "mgrCode" : "(idx4 custom text) MAT-A-1001", "safeQty" : 2345678 },
        { "matType" : "(idx0 text) 전자부품", "itemName" : "(idx1 text) 세라믹 커패시터 0.1uF", "stockQty" : 2345678, "stockAmt" : 8765432109, "mgrCode" : "(idx4 custom text) MAT-A-1002", "safeQty" : 3456789 },
        { "matType" : "(idx0 text) 기계부품", "itemName" : "(idx1 text) 육각 볼트 M6 30mm", "stockQty" : 3456789, "stockAmt" : 7654321098, "mgrCode" : "(idx4 custom text) MAT-B-2001", "safeQty" : 4567890 },
        { "matType" : "(idx0 text) 기계부품", "itemName" : "(idx1 text) 평와셔 M6 스테인리스", "stockQty" : 4567890, "stockAmt" : 6543210987, "mgrCode" : "(idx4 custom text) MAT-B-2002", "safeQty" : 5678901 },
        { "matType" : "(idx0 text) 소모자재", "itemName" : "(idx1 text) 무연 솔더 와이어 0.8mm", "stockQty" : 5678901, "stockAmt" : 5432109876, "mgrCode" : "(idx4 custom text) MAT-C-3001", "safeQty" : 6789012 }
    ];
    dlt_bind.setJSON(jsonData, false);

    // target 생성 (DataList 바인딩)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:900px;height:340px;">';
    strTarget += '<w2:caption style="" id="caption1" value="advancedExcelDownload (표시 형식 / 필터 옵션) 테스트 그리드"></w2:caption>';
    // Header : 2줄(MultiLine) - Header Row 인덱스 0 / 1 (filterRowIndex 확인용)
    //  Header Column 에도 dataType 지정 (useHeaderDataFormat 확인용)
    strTarget += '<w2:header style="" id="header1">';
    // Header Row 인덱스 0 (한글 명칭)
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="130" style="" inputType="text" dataType="text" id="hcol_type" value="자재 구분"></w2:column>';
    strTarget += '<w2:column width="200" style="" inputType="text" dataType="text" id="hcol_item" value="품목명"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" dataType="number" id="hcol_qty" value="재고수량"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" dataType="bigDecimal" id="hcol_amt" value="재고금액"></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" dataType="text" id="hcol_code" value="관리코드"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" dataType="number" id="hcol_safe" value="안전재고"></w2:column>';
    strTarget += '</w2:row>';
    // Header Row 인덱스 1 (영문 코드명)
    strTarget += '<w2:row style="" id="hrow2">';
    strTarget += '<w2:column width="130" style="" inputType="text" dataType="text" id="hcol_type2" value="MAT_TYPE"></w2:column>';
    strTarget += '<w2:column width="200" style="" inputType="text" dataType="text" id="hcol_item2" value="ITEM_NAME"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" dataType="number" id="hcol_qty2" value="STOCK_QTY"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" dataType="bigDecimal" id="hcol_amt2" value="STOCK_AMT"></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" dataType="text" id="hcol_code2" value="MGR_CODE"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" dataType="number" id="hcol_safe2" value="SAFE_QTY"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    // Body : dataType 이 서로 다른 Column 구성
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="130" style="" inputType="text" dataType="text" id="matType" dataList="matType"></w2:column>';
    strTarget += '<w2:column width="200" style="" inputType="text" dataType="text" id="itemName" dataList="itemName"></w2:column>';
    strTarget += '<w2:column width="110" style="text-align:right;" inputType="text" dataType="number" displayFormat="#,##0" id="stockQty" dataList="stockQty"></w2:column>';
    strTarget += '<w2:column width="120" style="text-align:right;" inputType="text" dataType="bigDecimal" id="stockAmt" dataList="stockAmt"></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="custom" dataType="text" typeGetter="scwin.target1_customTypeGetter" id="mgrCode" dataList="mgrCode"></w2:column>';
    strTarget += '<w2:column width="*" style="text-align:right;" inputType="custom" dataType="number" typeGetter="scwin.target1_customTypeGetter" id="safeQty" dataList="safeQty"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// inputType="custom" Column 의 Cell 구성 정보를 반환한다. (custom Column 이 정상 렌더/편집되도록 text 로 구성)
scwin.target1_customTypeGetter = function (info) {
    return { "id" : "cell_custom_" + info.rowIndex + "_" + info.colIndex, "inputType" : "text", "options" : {} };
}



// par 옵션값으로 advancedExcelDownload options 객체를 구성한다.
//  · 선택(필수여부 N) 파라미터는 미설정(빈값) 이면 객체에 담지 않아 생략되도록 한다.
//  · numberToText 는 Boolean, filterRowIndex 는 Number 타입 파라미터이므로 해당 타입으로 변환하여 전달한다.
//  · fileName / extension 은 다운로드 파일 확인 편의를 위한 고정값이며 본 계열의 검증 대상이 아니다.
scwin.buildOptions = function () {
    let options = { "fileName" : "download_xlsformat", "extension" : "xlsx" };
    let arrDesc = [];

    let fnSet = function (sKey, vValue) {
        options[sKey] = vValue;
        arrDesc.push(sKey + "=" + vValue);
    };

    let v;
    v = par_useDataFormat.getValue();       if (v !== "") fnSet("useDataFormat", v);
    v = par_useHeaderDataFormat.getValue(); if (v !== "") fnSet("useHeaderDataFormat", v);
    v = par_customToDataType.getValue();    if (v !== "") fnSet("customToDataType", v);
    v = par_numberToText.getValue();        if (v !== "") fnSet("numberToText", (v === "true"));
    v = par_headerAutoFilter.getValue();    if (v !== "") fnSet("headerAutoFilter", v);
    v = par_filterRowIndex.getValue();      if (v !== "") fnSet("filterRowIndex", parseInt(v, 10));

    return { "options" : options, "desc" : ((arrDesc.length === 0) ? "{} (useDataFormat / useHeaderDataFormat / customToDataType / numberToText / headerAutoFilter / filterRowIndex 전체 생략)" : arrDesc.join(" / ")) };
}



// 다운로드 요청 캡처 : 다운로드는 숨겨진 iframe 으로 form 전송되며 form 은 전송 직후 제거되므로,
//  메소드 호출 구간에서만 form submit 을 감싸 서버로 실제 전달되는 값을 읽고 곧바로 원복한다. (실제 요청은 그대로 통과)
scwin.hookRequest = function () {
    scwin.gVar = { "body" : "" };

    let fnSubmit = HTMLFormElement.prototype.submit;
    HTMLFormElement.prototype.submit = function () {
        if (scwin.gVar.body === "") {
            let objInput = this.querySelector("input[name=xmlValue]");
            scwin.gVar.body = (objInput === null) ? "" : objInput.value;
        }
        return fnSubmit.apply(this, arguments);
    };

    scwin.gVar.unhook = function () {
        HTMLFormElement.prototype.submit = fnSubmit;
    };
}



// 캡처한 요청 본문에서 서버로 전달된 옵션값을 읽는다. (전달되지 않은 옵션은 미전달로 표시)
scwin.getSentValue = function (sKey) {
    let sBody = scwin.gVar.body || "";
    let nKey = sBody.indexOf("hashkey='" + sKey + "'");
    if (nKey < 0) return "(미전달)";

    let sRest = sBody.substring(nKey);
    let nVal = sRest.indexOf("value='");
    if (nVal < 0) return "(미전달)";

    sRest = sRest.substring(nVal + 7);
    return sRest.substring(0, sRest.indexOf("'"));
}



// advancedExcelDownload 실행
scwin.btn_advancedExcelDownload_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let objBuild = scwin.buildOptions();

    scwin.hookRequest();
    try {
        target1.advancedExcelDownload(objBuild.options);
    } finally {
        scwin.gVar.unhook();
    }

    bottom.setReturnValue("전달 옵션 : " + objBuild.desc);
    bottom.setReturnValue("서버 전달값 : useDataFormat=" + scwin.getSentValue("useDataFormat") + " / useHeaderDataFormat=" + scwin.getSentValue("useHeaderDataFormat") + " / customToDataType=" + scwin.getSentValue("customToDataType"));
    bottom.setReturnValue("서버 전달값 : numberToText=" + scwin.getSentValue("numberToText") + " / headerAutoFilter=" + scwin.getSentValue("headerAutoFilter") + " / filterRowIndex=" + scwin.getSentValue("filterRowIndex"));
}
